#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <fstream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::string line;

    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        int n;
        std::string s;
        if (!(iss >> n >> s))
            break;

        bool ok = false;
        int one = 0;
        std::string tt = "";
        std::string twoans = "";
        bool wordnok = true;

        for (int c = 0; c < n; c++) {
            char ch = s[c];
            if (ch == '(') {
                ok = true;
                wordnok = true;
                tt.clear();
            } else if (ch == ')') {
                tt.clear();
                ok = false;
            } else {
                if (!ok) {
                    if (ch == '_') {
                        tt.clear();
                    } else {
                        tt += ch;
                    }
                    if ((int)tt.length() > (int)twoans.length()) {
                        twoans = tt;
                    }
                } else {
                    if (ch == '_') {
                        wordnok = true;
                    } else {
                        if (wordnok) {
                            one++;
                            wordnok = false;
                        }
                    }
                }
            }
        }

        std::cout << twoans.length() << " " << one << "\n";
    }

    return 0;
}
